package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.file.Path;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.DirectAdjacencyMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/** GQL must enter the ordinary repository pipeline and execute against LMDB's adjacency-backed source. */
class GqlLmdbEvaluationTest {

	private static final IRI ALICE = SimpleValueFactory.getInstance().createIRI("urn:gql:alice");
	private static final IRI BOB = SimpleValueFactory.getInstance().createIRI("urn:gql:bob");
	private static final IRI KNOWS = SimpleValueFactory.getInstance().createIRI("urn:gql:knows");

	@Test
	void evaluatesGqlThroughTheRepositoryApi(@TempDir Path directory) {
		LmdbStore store = new LmdbStore(directory.toFile(), new LmdbStoreConfig("spoc,posc")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyBuildOnStart(false)
				.setDirectAdjacencyMaxBytes(LmdbStoreConfig.DIRECT_ADJACENCY_MIN_EXPLICIT_BYTES));
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.add(ALICE, KNOWS, BOB);
				assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
				var query = connection.prepareTupleQuery(new QueryLanguage("GQL"),
						"MATCH (a)-[e]->(b) RETURN a, b");
				query.setIncludeInferred(false);
				try (var result = query.evaluate()) {
					assertThat(result.getBindingNames()).containsExactly("a", "b");
					assertThat(result.hasNext()).isTrue();
					var row = result.next();
					assertThat(row.getValue("a")).isEqualTo(ALICE);
					assertThat(row.getValue("b")).isEqualTo(BOB);
					assertThat(result.hasNext()).isFalse();
				}
			}
		} finally {
			repository.shutDown();
		}
	}
}
